let __v_3534 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"sonnet\",\"sonnets\"]},\"A sonnet is fourteen lines in iambic pentameter - ten syllables a line, stress on every second one. Shakespeare's kind rhymes in three quatrains and a closing couplet (abab cdcd efef gg) and turns at line nine; the Italian kind splits six and eight.\"]},{\"$tuple\":[{\"$tuple\":[\"stanza\",\"stanzas\",\"verse paragraph\"]},\"A stanza is a group of lines set apart in a poem, the way a paragraph is in prose. Two lines are a couplet, four a quatrain, and the pattern of rhymes across them is the rhyme scheme.\"]},{\"$tuple\":[{\"$tuple\":[\"free verse\",\"free-verse\"]},\"Free verse is poetry with no fixed metre and no rhyme: the line breaks and the rhythm of the sentences do the work instead. Most modern poetry is written this way.\"]},{\"$tuple\":[{\"$tuple\":[\"iambic pentameter\",\"iambic\",\"pentameter\",\"blank verse\"]},\"Iambic pentameter is five beats of da-DUM to the line - ten syllables with the stress on every second one: 'Shall I compare thee to a summer's day'. Blank verse is that without rhyme, which is what most of Shakespeare's plays are in.\"]},{\"$tuple\":[{\"$tuple\":[\"couplet\",\"couplets\"]},\"A couplet is two lines that rhyme and usually stand together: 'Good night, good night! Parting is such sweet sorrow / That I shall say good night till it be morrow.'\"]},{\"$tuple\":[{\"$tuple\":[\"ballad\",\"ballads\"]},\"A ballad is a story told in short verses, meant to be sung or recited: four-line stanzas that rhyme abab or abcb, with a refrain that comes back. The old folk ballads are the kind that run to a dozen verses, and pop still uses the name for a slow song about one feeling.\"]}]}")?;
